<h1>Location Management</h1><a class='btn' href='<?= url('locations/create') ?>'>Add Location</a><table><tr><th>ID</th><th>District</th><th>City</th><th>Postcode</th><th>Zone</th><th>Popular</th><th>Actions</th></tr><?php foreach($locations as $l): ?><tr><td><?= e($l['location_id']) ?></td><td><?= e($l['district']) ?></td><td><?= e($l['city']) ?></td><td><?= e($l['postcode']) ?></td><td><?= e($l['transport_zone']) ?></td><td><?= $l['is_popular']?'Yes':'No' ?></td><td><a href='<?= url('locations/edit?id='.$l['location_id']) ?>'>Edit</a> | <a onclick="return confirm('Delete location?')" href='<?= url('locations/delete?id='.$l['location_id']) ?>'>Delete</a></td></tr><?php endforeach; ?></table>
